#include <stdio.h>

/* teste do desafio o-teto-e-o-piso — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   A captura do stdout acontece dentro do proprio cenario: freopen manda o
   stdout para o arquivo temporario, o teste chama a funcao do aluno e le o
   arquivo de volta (fflush sem fclose no stdout). Os numeros esperados sao
   os medidos nesta maquina para o int de 4 bytes. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void oTetoEOPiso(void);

SM_TEST(o_teto_e_o_piso_nesta_ordem) {
    freopen("sm_saida.tmp", "w", stdout);
    oTetoEOPiso();
    fflush(stdout);

    FILE *f = fopen("sm_saida.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a primeira linha e o teto do int", linha, "2147483647\n",
              "o maior int que cabe nesta maquina vem do inventario dos limites");
    fgets(linha, 80, f);
    checa_str("a segunda linha e o piso do int", linha, "-2147483648\n",
              "o menor int esta uma unidade mais longe do zero que o teto");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida acaba na segunda linha: nenhuma linha extra e aceita");
    fclose(f);
}

